import os
from typing import Any, Dict, Optional

import requests


OKTA_DOMAIN = os.getenv("OKTA_DOMAIN", "").rstrip("/")
OKTA_API_TOKEN = os.getenv("OKTA_API_TOKEN", "")


class FederatedProfileError(Exception):
    pass


def _normalize_claims(raw: Dict[str, Any]) -> Dict[str, Any]:
    profile = raw.get("profile") if isinstance(raw.get("profile"), dict) else raw

    normalized = {
        "provider": "okta",
        "subject": profile.get("sub") or profile.get("id") or raw.get("id"),
        "email": profile.get("email") or raw.get("email"),
        "email_verified": profile.get("email_verified"),
        "first_name": profile.get("given_name") or profile.get("firstName") or profile.get("first_name"),
        "last_name": profile.get("family_name") or profile.get("lastName") or profile.get("last_name"),
        "full_name": profile.get("name")
        or " ".join(
            part
            for part in [
                profile.get("given_name") or profile.get("first_name"),
                profile.get("family_name") or profile.get("last_name"),
            ]
            if part
        )
        or None,
        "picture": profile.get("picture") or profile.get("profilePicture"),
        "locale": profile.get("locale"),
        "groups": profile.get("groups") or raw.get("groups") or [],
        "raw": raw,
    }

    return normalized


def fetch_federated_user_profile(access_token: str, timeout: int = 10) -> Dict[str, Any]:
    if not OKTA_DOMAIN:
        raise FederatedProfileError("OKTA_DOMAIN environment variable is required")
    if not OKTA_API_TOKEN:
        raise FederatedProfileError("OKTA_API_TOKEN environment variable is required")
    if not access_token:
        raise FederatedProfileError("access_token is required")

    url = f"{OKTA_DOMAIN}/oauth2/v1/userinfo"
    headers = {
        "Authorization": f"Bearer {access_token}",
        "Accept": "application/json",
        "Content-Type": "application/json",
        "Authorization-Token": OKTA_API_TOKEN,
    }

    response = requests.get(url, headers=headers, timeout=timeout)
    if response.status_code != 200:
        raise FederatedProfileError(
            f"Failed to fetch federated profile from Okta: {response.status_code} {response.text}"
        )

    try:
        raw_claims = response.json()
    except ValueError as exc:
        raise FederatedProfileError("Okta response was not valid JSON") from exc

    if not isinstance(raw_claims, dict):
        raise FederatedProfileError("Okta response JSON must be an object")

    return _normalize_claims(raw_claims)
